describe("Cart – totals / pricing pipeline", () => {
  it("computes subtotal as sum of unitPriceCents * quantity", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 2);
    cart.add(product("b", 500), 3);
    const t = cart.totals();
    expect(t.subtotalCents).toBe(3500); // 2000 + 1500
  });

  it("empty cart returns all-zero totals", () => {
    const t = new Cart().totals();
    expect(t).toEqual({
      subtotalCents: 0,
      discountCents: 0,
      taxCents: 0,
      shippingCents: 0,
      totalCents: 0,
    });
  });

  it("applies discount then tax on discounted subtotal", () => {
    const cart = new Cart({
      discountPolicy: new PercentageDiscountPolicy(10),
      taxCalculator: new RegionalTaxCalculator({ "US": 0.1 }),
      region: "US",
    });
    cart.add(product("a", 10000), 1);
    const t = cart.totals();
    // subtotal 10000, discount 1000, taxable 9000, tax 900
    expect(t.subtotalCents).toBe(10000);
    expect(t.discountCents).toBe(1000);
    expect(t.taxCents).toBe(900);
    expect(t.totalCents).toBe(9000 + 900);
  });

  it("clamps discount to [0, subtotal]", () => {
    // Use a mock discount policy that returns more than subtotal
    const overPolicy: DiscountPolicy = {
      computeDiscountCents: () => 999999,
    };
    const cart = new Cart({ discountPolicy: overPolicy });
    cart.add(product("a", 1000), 1);
    const t = cart.totals();
    expect(t.discountCents).toBe(1000); // clamped to subtotal
    expect(t.totalCents).toBe(0);
  });

  it("clamps negative discount to 0", () => {
    const negPolicy: DiscountPolicy = {
      computeDiscountCents: () => -500,
    };
    const cart = new Cart({ discountPolicy: negPolicy });
    cart.add(product("a", 1000), 1);
    const t = cart.totals();
    expect(t.discountCents).toBe(0);
  });

  it("shipping is computed against discounted subtotal and lines", () => {
    // Flat shipping with free-over threshold at 5000
    const cart = new Cart({
      discountPolicy: new FixedAmountDiscountPolicy(2000),
      shippingCalculator: new FlatShippingCalculator(599, 5000),
    });
    cart.add(product("a", 6000), 1);
    const t = cart.totals();
    // subtotal 6000, discount 2000, discounted 4000 < 5000 → shipping 599
    expect(t.shippingCents).toBe(599);
    expect(t.totalCents).toBe(4000 + 599);
  });

  it("defaults to NoDiscount, NoTax, FreeShipping, region US", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 1);
    const t = cart.totals();
    expect(t.discountCents).toBe(0);
    expect(t.taxCents).toBe(0);
    expect(t.shippingCents).toBe(0);
    expect(t.totalCents).toBe(1000);
  });

  it("clamps negative tax to 0", () => {
    const negTax: TaxCalculator = { computeTaxCents: () => -100 };
    const cart = new Cart({ taxCalculator: negTax });
    cart.add(product("a", 1000), 1);
    expect(cart.totals().taxCents).toBe(0);
  });

  it("clamps negative shipping to 0", () => {
    const negShip: ShippingCalculator = {
      computeShippingCents: () => -100,
    };
    const cart = new Cart({ shippingCalculator: negShip });
    cart.add(product("a", 1000), 1);
    expect(cart.totals().shippingCents).toBe(0);
  });
});

describe("Cart – checkout()", () => {
  it("basic checkout without collaborators", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 2);
    const result = await cart.checkout();
    expect(result.totals.subtotalCents).toBe(2000);
    expect(result.lines).toHaveLength(1);
  });

  it("refreshes prices via priceFetcher", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 1);
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(1500),
    };
    const result = await cart.checkout({ priceFetcher: fetcher });
    expect(result.totals.subtotalCents).toBe(1500);
    expect(fetcher.fetchPriceCents).toHaveBeenCalledWith("a");
  });

  it("checks inventory and passes when available", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 2);
    const checker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true }),
    };
    const result = await cart.checkout({ inventoryChecker: checker });
    expect(result.totals.subtotalCents).toBe(2000);
    expect(checker.check).toHaveBeenCalledWith("a", 2);
  });

  it("throws InventoryError when item not available", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 5);
    const checker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: false,
        availableQuantity: 2,
        reason: "low stock",
      }),
    };
    try {
      await cart.checkout({ inventoryChecker: checker });
      expect.unreachable("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const ie = err as InventoryError;
      expect(ie.productId).toBe("a");
      expect(ie.requested).toBe(5);
      expect(ie.available).toBe(2);
    }
  });

  it("throws InventoryError on partial-stock denial (available:true but quantity insufficient)", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 10);
    const checker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 3,
      }),
    };
    try {
      await cart.checkout({ inventoryChecker: checker });
      expect.unreachable("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const ie = err as InventoryError;
      expect(ie.productId).toBe("a");
      expect(ie.requested).toBe(10);
      expect(ie.available).toBe(3);
    }
  });

  it("uses asyncTaxProvider for tax computation", async () => {
    const cart = new Cart({
      discountPolicy: new NoDiscountPolicy(),
      region: "US-CA",
    });
    cart.add(product("a", 10000), 1);
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.0875),
    };
    const result = await cart.checkout({ asyncTaxProvider: provider });
    // tax = floor(10000 * 0.0875) = 875
    expect(result.totals.taxCents).toBe(875);
    expect(provider.getRate).toHaveBeenCalledWith("US-CA");
  });

  it("combines discount + async tax + shipping", async () => {
    const cart = new Cart({
      discountPolicy: new PercentageDiscountPolicy(20),
      shippingCalculator: new FlatShippingCalculator(500),
      region: "US",
    });
    cart.add(product("a", 10000), 1);
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
    const result = await cart.checkout({ asyncTaxProvider: provider });
    // subtotal 10000, discount 2000, discounted 8000
    // tax = floor(8000 * 0.1) = 800
    // shipping = 500
    expect(result.totals.subtotalCents).toBe(10000);
    expect(result.totals.discountCents).toBe(2000);
    expect(result.totals.taxCents).toBe(800);
    expect(result.totals.shippingCents).toBe(500);
    expect(result.totals.totalCents).toBe(8000 + 800 + 500);
  });

  it("propagates priceFetcher failure", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 1);
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("price service down")),
    };
    await expect(cart.checkout({ priceFetcher: fetcher })).rejects.toThrow(
      "price service down",
    );
  });

  it("propagates asyncTaxProvider failure", async () => {
    const cart = new Cart({ region: "US" });
    cart.add(product("a", 1000), 1);
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
    };
    await expect(
      cart.checkout({ asyncTaxProvider: provider }),
    ).rejects.toThrow("tax service down");
  });

  it("checkout returns lines snapshot", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 1);
    const result = await cart.checkout();
    expect(result.lines).toHaveLength(1);
    expect(result.lines[0]!.product.id).toBe("a");
  });

  it("inventory check runs after price refresh", async () => {
    const cart = new Cart();
    cart.add(product("a", 500), 1);
    const callOrder: string[] = [];
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockImplementation(async () => {
        callOrder.push("fetch");
        return 600;
      }),
    };
    const checker: InventoryChecker = {
      check: vi.fn().mockImplementation(async () => {
        callOrder.push("check");
        return { available: true };
      }),
    };
    await cart.checkout({ priceFetcher: fetcher, inventoryChecker: checker });
    expect(callOrder).toEqual(["fetch", "check"]);
  });

  it("first denied item wins when multiple items fail inventory", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 1);
    cart.add(product("b", 2000), 1);
    const checker: InventoryChecker = {
      check: vi.fn()
        .mockResolvedValueOnce({ available: false, reason: "a out" })
        .mockResolvedValueOnce({ available: false, reason: "b out" }),
    };
    try {
      await cart.checkout({ inventoryChecker: checker });
      expect.unreachable("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      // Only first check triggers error; second is never reached
      expect(checker.check).toHaveBeenCalledTimes(1);
    }
  });
});

import { describe, it, expect } from "vitest";
import {
  NoDiscountPolicy,
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
  CompositeDiscountPolicy,
} from "../src/pricing.ts";

describe("NoDiscountPolicy", () => {
  const policy = new NoDiscountPolicy();

  it("returns 0 for positive subtotal", () => {
    expect(policy.computeDiscountCents(10000)).toBe(0);
  });

  it("returns 0 for zero subtotal", () => {
    expect(policy.computeDiscountCents(0)).toBe(0);
  });

  it("returns 0 for negative subtotal", () => {
    expect(policy.computeDiscountCents(-500)).toBe(0);
  });
});

describe("PercentageDiscountPolicy", () => {
  it("rejects negative percent", () => {
    expect(() => new PercentageDiscountPolicy(-1)).toThrow(RangeError);
  });

  it("rejects percent > 100", () => {
    expect(() => new PercentageDiscountPolicy(101)).toThrow(RangeError);
  });

  it("rejects NaN", () => {
    expect(() => new PercentageDiscountPolicy(NaN)).toThrow(RangeError);
  });

  it("rejects Infinity", () => {
    expect(() => new PercentageDiscountPolicy(Infinity)).toThrow(RangeError);
  });

  it("accepts 0%", () => {
    const p = new PercentageDiscountPolicy(0);
    expect(p.computeDiscountCents(10000)).toBe(0);
  });

  it("accepts 100%", () => {
    const p = new PercentageDiscountPolicy(100);
    expect(p.computeDiscountCents(10000)).toBe(10000);
  });

  it("computes 10% of 9999 (rounds down)", () => {
    const p = new PercentageDiscountPolicy(10);
    // 9999 * 10 / 100 = 999.9 → floor → 999
    expect(p.computeDiscountCents(9999)).toBe(999);
  });

  it("returns 0 for zero subtotal", () => {
    const p = new PercentageDiscountPolicy(50);
    expect(p.computeDiscountCents(0)).toBe(0);
  });

  it("returns 0 for negative subtotal", () => {
    const p = new PercentageDiscountPolicy(50);
    expect(p.computeDiscountCents(-100)).toBe(0);
  });

  it("handles very large subtotal", () => {
    const p = new PercentageDiscountPolicy(15);
    expect(p.computeDiscountCents(100_000_000)).toBe(15_000_000);
  });
});

describe("FixedAmountDiscountPolicy", () => {
  it("rejects negative amount", () => {
    expect(() => new FixedAmountDiscountPolicy(-1)).toThrow(RangeError);
  });

  it("rejects non-integer amount", () => {
    expect(() => new FixedAmountDiscountPolicy(10.5)).toThrow(RangeError);
  });

  it("accepts 0", () => {
    const p = new FixedAmountDiscountPolicy(0);
    expect(p.computeDiscountCents(5000)).toBe(0);
  });

  it("returns the fixed amount when subtotal exceeds it", () => {
    const p = new FixedAmountDiscountPolicy(500);
    expect(p.computeDiscountCents(5000)).toBe(500);
  });

  it("caps at subtotal when discount exceeds subtotal", () => {
    const p = new FixedAmountDiscountPolicy(5000);
    expect(p.computeDiscountCents(2000)).toBe(2000);
  });

  it("returns 0 for zero subtotal", () => {
    const p = new FixedAmountDiscountPolicy(500);
    expect(p.computeDiscountCents(0)).toBe(0);
  });

  it("returns 0 for negative subtotal", () => {
    const p = new FixedAmountDiscountPolicy(500);
    expect(p.computeDiscountCents(-100)).toBe(0);
  });
});

describe("CompositeDiscountPolicy", () => {
  it("rejects empty policy list", () => {
    expect(() => new CompositeDiscountPolicy([])).toThrow(
      "at least one policy",
    );
  });

  describe("sum mode", () => {
    it("sums discounts from all policies against original subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10), // 1000
          new FixedAmountDiscountPolicy(500), // 500
        ],
        "sum",
      );
      expect(composite.computeDiscountCents(10000)).toBe(1500);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(100)],
        "sum",
      );
      expect(composite.computeDiscountCents(-50)).toBe(0);
    });

    it("sum can exceed subtotal (Cart clamps later)", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new FixedAmountDiscountPolicy(800),
          new FixedAmountDiscountPolicy(800),
        ],
        "sum",
      );
      // Each gets min(800, 1000) = 800 → total 1600 > 1000
      expect(composite.computeDiscountCents(1000)).toBe(1600);
    });

    it("defaults to sum mode when mode omitted", () => {
      const composite = new CompositeDiscountPolicy([
        new PercentageDiscountPolicy(10),
        new FixedAmountDiscountPolicy(200),
      ]);
      // 10% of 5000 = 500, fixed 200 → 700
      expect(composite.computeDiscountCents(5000)).toBe(700);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially on remaining subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10), // 10% of 10000 = 1000
          new FixedAmountDiscountPolicy(500), // 500 off remaining 9000
        ],
        "chain",
      );
      expect(composite.computeDiscountCents(10000)).toBe(1500);
    });

    it("order matters in chain mode", () => {
      const policiesA = [
        new PercentageDiscountPolicy(50), // 50% of 10000 = 5000, remaining 5000
        new PercentageDiscountPolicy(50), // 50% of 5000 = 2500
      ];
      const policiesB = [
        new PercentageDiscountPolicy(50), // same result due to symmetry
        new PercentageDiscountPolicy(50),
      ];
      const a = new CompositeDiscountPolicy(policiesA, "chain");
      const b = new CompositeDiscountPolicy(policiesB, "chain");
      expect(a.computeDiscountCents(10000)).toBe(7500);
      expect(b.computeDiscountCents(10000)).toBe(7500);
    });

    it("chain cannot exceed subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new FixedAmountDiscountPolicy(600),
          new FixedAmountDiscountPolicy(600),
        ],
        "chain",
      );
      // First: min(600, 1000) = 600, remaining = 400
      // Second: min(600, 400) = 400, remaining = 0
      expect(composite.computeDiscountCents(1000)).toBe(1000);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(100)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("chain with percentage then fixed shows compounding", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(20), // 20% of 1000 = 200 → remaining 800
          new FixedAmountDiscountPolicy(300), // min(300,800) = 300
        ],
        "chain",
      );
      expect(composite.computeDiscountCents(1000)).toBe(500);
    });
  });
});

