import type { ShippingCalculator } from "../src/shipping.ts";
import { FlatShippingCalculator } from "../src/shipping.ts";
import { InventoryError } from "../src/inventory.ts";
import type { Product } from "../src/product.ts";
import type { PriceFetcher, InventoryChecker } from "../src/inventory.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";

const product = (
  id: string,
  price: number,
  weight?: number,
): Product => ({
  id,
  name: `Product ${id}`,
  unitPriceCents: price,
  ...(weight !== undefined ? { weightGrams: weight } : {}),
});

describe("Cart – line management", () => {
  it("add creates a line", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 2);
    expect(cart.itemCount).toBe(2);
  });

  it("add merges quantity for same product", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 2);
    cart.add(product("a", 1000), 3);
    expect(cart.itemCount).toBe(5);
  });

  it("add rejects non-positive quantity", () => {
    const cart = new Cart();
    expect(() => cart.add(product("a", 1000), 0)).toThrow(RangeError);
    expect(() => cart.add(product("a", 1000), -1)).toThrow(RangeError);
  });

  it("add rejects non-integer quantity", () => {
    const cart = new Cart();
    expect(() => cart.add(product("a", 1000), 1.5)).toThrow(RangeError);
  });

  it("add rejects negative unitPriceCents", () => {
    const cart = new Cart();
    expect(() => cart.add(product("a", -1), 1)).toThrow(RangeError);
  });

  it("remove deletes existing product", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 1);
    expect(cart.remove("a")).toBe(true);
    expect(cart.itemCount).toBe(0);
  });

  it("remove returns false for unknown id", () => {
    const cart = new Cart();
    expect(cart.remove("nonexistent")).toBe(false);
  });

  it("updateQuantity changes quantity", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 5);
    cart.updateQuantity("a", 3);
    expect(cart.itemCount).toBe(3);
  });

  it("updateQuantity 0 removes the line", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 5);
    cart.updateQuantity("a", 0);
    expect(cart.itemCount).toBe(0);
  });

  it("updateQuantity throws for unknown product", () => {
    const cart = new Cart();
    expect(() => cart.updateQuantity("x", 1)).toThrow("not in the cart");
  });

  it("updateQuantity rejects negative", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 1);
    expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
  });

  it("updateQuantity rejects non-integer", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 1);
    expect(() => cart.updateQuantity("a", 1.5)).toThrow(RangeError);
  });

  it("clear empties the cart", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 2);
    cart.add(product("b", 2000), 1);
    cart.clear();
    expect(cart.itemCount).toBe(0);
  });

  it("snapshot returns a deep copy", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 1);
    const snap = cart.snapshot();
    (snap[0] as any).quantity = 99;
    expect(cart.itemCount).toBe(1);
  });
});

describe("Cart – totals / pricing pipeline", () => {
  it("computes subtotal as sum of unitPriceCents * quantity", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 2);
    cart.add(product("b", 500), 3);
    const t = cart.totals();
    expect(t.subtotalCents).toBe(3500); // 2000 + 1500
  });

  it("empty cart returns all-zero totals", () => {
    const t = new Cart().totals();
    expect(t).toEqual({
      subtotalCents: 0,
      discountCents: 0,
      taxCents: 0,
      shippingCents: 0,
      totalCents: 0,
    });
  });

  it("applies discount then tax on discounted subtotal", () => {
    const cart = new Cart({
      discountPolicy: new PercentageDiscountPolicy(10),
      taxCalculator: new RegionalTaxCalculator({ "US": 0.1 }),
      region: "US",
    });
    cart.add(product("a", 10000), 1);
    const t = cart.totals();
    // subtotal 10000, discount 1000, taxable 9000, tax 900
    expect(t.subtotalCents).toBe(10000);
    expect(t.discountCents).toBe(1000);
    expect(t.taxCents).toBe(900);
    expect(t.totalCents).toBe(9000 + 900);
  });

  it("clamps discount to [0, subtotal]", () => {
    // Use a mock discount policy that returns more than subtotal
    const overPolicy: DiscountPolicy = {
      computeDiscountCents: () => 999999,
    };
    const cart = new Cart({ discountPolicy: overPolicy });
    cart.add(product("a", 1000), 1);
    const t = cart.totals();
    expect(t.discountCents).toBe(1000); // clamped to subtotal
    expect(t.totalCents).toBe(0);
  });

  it("clamps negative discount to 0", () => {
    const negPolicy: DiscountPolicy = {
      computeDiscountCents: () => -500,
    };
    const cart = new Cart({ discountPolicy: negPolicy });
    cart.add(product("a", 1000), 1);
    const t = cart.totals();
    expect(t.discountCents).toBe(0);
  });

  it("shipping is computed against discounted subtotal and lines", () => {
    // Flat shipping with free-over threshold at 5000
    const cart = new Cart({
      discountPolicy: new FixedAmountDiscountPolicy(2000),
      shippingCalculator: new FlatShippingCalculator(599, 5000),
    });
    cart.add(product("a", 6000), 1);
    const t = cart.totals();
    // subtotal 6000, discount 2000, discounted 4000 < 5000 → shipping 599
    expect(t.shippingCents).toBe(599);
    expect(t.totalCents).toBe(4000 + 599);
  });

  it("defaults to NoDiscount, NoTax, FreeShipping, region US", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 1);
    const t = cart.totals();
    expect(t.discountCents).toBe(0);
    expect(t.taxCents).toBe(0);
    expect(t.shippingCents).toBe(0);
    expect(t.totalCents).toBe(1000);
  });

  it("clamps negative tax to 0", () => {
    const negTax: TaxCalculator = { computeTaxCents: () => -100 };
    const cart = new Cart({ taxCalculator: negTax });
    cart.add(product("a", 1000), 1);
    expect(cart.totals().taxCents).toBe(0);
  });

  it("clamps negative shipping to 0", () => {
    const negShip: ShippingCalculator = {
      computeShippingCents: () => -100,
    };
    const cart = new Cart({ shippingCalculator: negShip });
    cart.add(product("a", 1000), 1);
    expect(cart.totals().shippingCents).toBe(0);
  });
});

