  });

  it("inventory check runs after price refresh", async () => {
    const cart = new Cart();
    cart.add(product("a", 500), 1);
    const callOrder: string[] = [];
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockImplementation(async () => {
        callOrder.push("fetch");
        return 600;
      }),
    };
    const checker: InventoryChecker = {
      check: vi.fn().mockImplementation(async () => {
        callOrder.push("check");
        return { available: true };
      }),
    };
    await cart.checkout({ priceFetcher: fetcher, inventoryChecker: checker });
    expect(callOrder).toEqual(["fetch", "check"]);
  });

  it("first denied item wins when multiple items fail inventory", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 1);
    cart.add(product("b", 2000), 1);
    const checker: InventoryChecker = {
      check: vi.fn()
        .mockResolvedValueOnce({ available: false, reason: "a out" })
        .mockResolvedValueOnce({ available: false, reason: "b out" }),
    };
    try {
      await cart.checkout({ inventoryChecker: checker });
      expect.unreachable("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      // Only first check triggers error; second is never reached
      expect(checker.check).toHaveBeenCalledTimes(1);
    }
  });
});

