describe("CompositeDiscountPolicy", () => {
  it("rejects empty policy list", () => {
    expect(() => new CompositeDiscountPolicy([])).toThrow(
      "at least one policy",
    );
  });

  describe("sum mode", () => {
    it("sums discounts from all policies against original subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10), // 1000
          new FixedAmountDiscountPolicy(500), // 500
        ],
        "sum",
      );
      expect(composite.computeDiscountCents(10000)).toBe(1500);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(100)],
        "sum",
      );
      expect(composite.computeDiscountCents(-50)).toBe(0);
    });

    it("sum can exceed subtotal (Cart clamps later)", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new FixedAmountDiscountPolicy(800),
          new FixedAmountDiscountPolicy(800),
        ],
        "sum",
      );
      // Each gets min(800, 1000) = 800 → total 1600 > 1000
      expect(composite.computeDiscountCents(1000)).toBe(1600);
    });

    it("defaults to sum mode when mode omitted", () => {
      const composite = new CompositeDiscountPolicy([
        new PercentageDiscountPolicy(10),
        new FixedAmountDiscountPolicy(200),
      ]);
      // 10% of 5000 = 500, fixed 200 → 700
      expect(composite.computeDiscountCents(5000)).toBe(700);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially on remaining subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10), // 10% of 10000 = 1000
          new FixedAmountDiscountPolicy(500), // 500 off remaining 9000
        ],
        "chain",
      );
      expect(composite.computeDiscountCents(10000)).toBe(1500);
    });

    it("order matters in chain mode", () => {
      const policiesA = [
        new PercentageDiscountPolicy(50), // 50% of 10000 = 5000, remaining 5000
        new PercentageDiscountPolicy(50), // 50% of 5000 = 2500
      ];
      const policiesB = [
        new PercentageDiscountPolicy(50), // same result due to symmetry
        new PercentageDiscountPolicy(50),
      ];
      const a = new CompositeDiscountPolicy(policiesA, "chain");
      const b = new CompositeDiscountPolicy(policiesB, "chain");
      expect(a.computeDiscountCents(10000)).toBe(7500);
      expect(b.computeDiscountCents(10000)).toBe(7500);
    });

    it("chain cannot exceed subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new FixedAmountDiscountPolicy(600),
          new FixedAmountDiscountPolicy(600),
        ],
        "chain",
      );
      // First: min(600, 1000) = 600, remaining = 400
      // Second: min(600, 400) = 400, remaining = 0
      expect(composite.computeDiscountCents(1000)).toBe(1000);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(100)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("chain with percentage then fixed shows compounding", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(20), // 20% of 1000 = 200 → remaining 800
          new FixedAmountDiscountPolicy(300), // min(300,800) = 300
        ],
        "chain",
      );
      expect(composite.computeDiscountCents(1000)).toBe(500);
    });
  });
});
"}

