    cart.add(product("a", 1000), 1);
    expect(cart.remove("a")).toBe(true);
    expect(cart.itemCount).toBe(0);
  });

  it("remove returns false for unknown id", () => {
    const cart = new Cart();
    expect(cart.remove("nonexistent")).toBe(false);
  });

  it("updateQuantity changes quantity", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 5);
    cart.updateQuantity("a", 3);
    expect(cart.itemCount).toBe(3);
  });

  it("updateQuantity 0 removes the line", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 5);
    cart.updateQuantity("a", 0);
    expect(cart.itemCount).toBe(0);
  });

  it("updateQuantity throws for unknown product", () => {
    const cart = new Cart();
    expect(() => cart.updateQuantity("x", 1)).toThrow("not in the cart");
  });

  it("updateQuantity rejects negative", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 1);
    expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
  });

  it("updateQuantity rejects non-integer", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 1);
    expect(() => cart.updateQuantity("a", 1.5)).toThrow(RangeError);
  });

  it("clear empties the cart", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 2);
    cart.add(product("b", 2000), 1);
    cart.clear();
    expect(cart.itemCount).toBe(0);
  });

  it("snapshot returns a deep copy", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 1);
    const snap = cart.snapshot();
    (snap[0] as any).quantity = 99;
    expect(cart.itemCount).toBe(1);
  });
});

describe("Cart – totals / pricing pipeline", () => {
  it("computes subtotal as sum of unitPriceCents * quantity", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 2);
    cart.add(product("b", 500), 3);
    const t = cart.totals();
    expect(t.subtotalCents).toBe(3500); // 2000 + 1500
  });

  it("empty cart returns all-zero totals", () => {
    const t = new Cart().totals();
    expect(t).toEqual({
      subtotalCents: 0,
      discountCents: 0,
      taxCents: 0,
      shippingCents: 0,
      totalCents: 0,
    });
  });

  it("applies discount then tax on discounted subtotal", () => {
    const cart = new Cart({
      discountPolicy: new PercentageDiscountPolicy(10),
      taxCalculator: new RegionalTaxCalculator({ "US": 0.1 }),
      region: "US",
    });
    cart.add(product("a", 10000), 1);
    const t = cart.totals();
    // subtotal 10000, discount 1000, taxable 9000, tax 900
    expect(t.subtotalCents).toBe(10000);
    expect(t.discountCents).toBe(1000);
    expect(t.taxCents).toBe(900);
    expect(t.totalCents).toBe(9000 + 900);
  });

  it("clamps discount to [0, subtotal]", () => {
    // Use a mock discount policy that returns more than subtotal
    const overPolicy: DiscountPolicy = {
      computeDiscountCents: () => 999999,
    };
    const cart = new Cart({ discountPolicy: overPolicy });
    cart.add(product("a", 1000), 1);
    const t = cart.totals();
    expect(t.discountCents).toBe(1000); // clamped to subtotal
    expect(t.totalCents).toBe(0);
  });

  it("clamps negative discount to 0", () => {
    const negPolicy: DiscountPolicy = {
      computeDiscountCents: () => -500,
    };
    const cart = new Cart({ discountPolicy: negPolicy });
    cart.add(product("a", 1000), 1);
    const t = cart.totals();
    expect(t.discountCents).toBe(0);
  });

  it("shipping is computed against discounted subtotal and lines", () => {
    // Flat shipping with free-over threshold at 5000
    const cart = new Cart({
      discountPolicy: new FixedAmountDiscountPolicy(2000),
      shippingCalculator: new FlatShippingCalculator(599, 5000),
    });
    cart.add(product("a", 6000), 1);
    const t = cart.totals();
    // subtotal 6000, discount 2000, discounted 4000 < 5000 → shipping 599
    expect(t.shippingCents).toBe(599);
    expect(t.totalCents).toBe(4000 + 599);
  });

  it("defaults to NoDiscount, NoTax, FreeShipping, region US", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 1);
    const t = cart.totals();
    expect(t.discountCents).toBe(0);
    expect(t.taxCents).toBe(0);
    expect(t.shippingCents).toBe(0);
    expect(t.totalCents).toBe(1000);
  });

  it("clamps negative tax to 0", () => {
    const negTax: TaxCalculator = { computeTaxCents: () => -100 };
    const cart = new Cart({ taxCalculator: negTax });
    cart.add(product("a", 1000), 1);
    expect(cart.totals().taxCents).toBe(0);
  });

  it("clamps negative shipping to 0", () => {
    const negShip: ShippingCalculator = {
      computeShippingCents: () => -100,
    };
    const cart = new Cart({ shippingCalculator: negShip });
    cart.add(product("a", 1000), 1);
    expect(cart.totals().shippingCents).toBe(0);
  });
});

describe("Cart – checkout()", () => {
  it("basic checkout without collaborators", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 2);
    const result = await cart.checkout();
    expect(result.totals.subtotalCents).toBe(2000);
    expect(result.lines).toHaveLength(1);
  });

  it("refreshes prices via priceFetcher", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 1);
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(1500),
    };
    const result = await cart.checkout({ priceFetcher: fetcher });
    expect(result.totals.subtotalCents).toBe(1500);
    expect(fetcher.fetchPriceCents).toHaveBeenCalledWith("a");
  });

  it("checks inventory and passes when available", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 2);
    const checker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true }),
    };
    const result = await cart.checkout({ inventoryChecker: checker });
    expect(result.totals.subtotalCents).toBe(2000);
    expect(checker.check).toHaveBeenCalledWith("a", 2);
  });

  it("throws InventoryError when item not available", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 5);
    const checker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: false,
        availableQuantity: 2,
        reason: "low stock",
      }),
    };
    try {
      await cart.checkout({ inventoryChecker: checker });
      expect.unreachable("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const ie = err as InventoryError;
      expect(ie.productId).toBe("a");
      expect(ie.requested).toBe(5);
      expect(ie.available).toBe(2);
    }
  });

  it("throws InventoryError on partial-stock denial (available:true but quantity insufficient)", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 10);
    const checker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 3,
      }),
    };
    try {
      await cart.checkout({ inventoryChecker: checker });
      expect.unreachable("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const ie = err as InventoryError;
      expect(ie.productId).toBe("a");
      expect(ie.requested).toBe(10);
      expect(ie.available).toBe(3);
    }
  });

  it("uses asyncTaxProvider for tax computation", async () => {
    const cart = new Cart({
      discountPolicy: new NoDiscountPolicy(),
      region: "US-CA",
    });
    cart.add(product("a", 10000), 1);
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.0875),
    };
    const result = await cart.checkout({ asyncTaxProvider: provider });
    // tax = floor(10000 * 0.0875) = 875
    expect(result.totals.taxCents).toBe(875);
    expect(provider.getRate).toHaveBeenCalledWith("US-CA");
  });

  it("combines discount + async tax + shipping", async () => {
    const cart = new Cart({
      discountPolicy: new PercentageDiscountPolicy(20),
      shippingCalculator: new FlatShippingCalculator(500),
      region: "US",
    });
    cart.add(product("a", 10000), 1);
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
    const result = await cart.checkout({ asyncTaxProvider: provider });
    // subtotal 10000, discount 2000, discounted 8000
    // tax = floor(8000 * 0.1) = 800
    // shipping = 500
    expect(result.totals.subtotalCents).toBe(10000);
    expect(result.totals.discountCents).toBe(2000);
    expect(result.totals.taxCents).toBe(800);
    expect(result.totals.shippingCents).toBe(500);
    expect(result.totals.totalCents).toBe(8000 + 800 + 500);
  });

  it("propagates priceFetcher failure", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 1);
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("price service down")),
    };
    await expect(cart.checkout({ priceFetcher: fetcher })).rejects.toThrow(
      "price service down",
    );
  });

  it("propagates asyncTaxProvider failure", async () => {
    const cart = new Cart({ region: "US" });
    cart.add(product("a", 1000), 1);
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
    };
    await expect(
      cart.checkout({ asyncTaxProvider: provider }),
    ).rejects.toThrow("tax service down");
  });

  it("checkout returns lines snapshot", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 1);
    const result = await cart.checkout();
    expect(result.lines).toHaveLength(1);
    expect(result.lines[0]!.product.id).toBe("a");
  });

  it("inventory check runs after price refresh", async () => {
    const cart = new Cart();
    cart.add(product("a", 500), 1);
    const callOrder: string[] = [];
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockImplementation(async () => {
        callOrder.push("fetch");
        return 600;
      }),
    };
    const checker: InventoryChecker = {
      check: vi.fn().mockImplementation(async () => {
        callOrder.push("check");
        return { available: true };
      }),
    };
    await cart.checkout({ priceFetcher: fetcher, inventoryChecker: checker });
    expect(callOrder).toEqual(["fetch", "check"]);
  });

  it("first denied item wins when multiple items fail inventory", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 1);
    cart.add(product("b", 2000), 1);
    const checker: InventoryChecker = {
      check: vi.fn()
        .mockResolvedValueOnce({ available: false, reason: "a out" })
        .mockResolvedValueOnce({ available: false, reason: "b out" }),
    };
    try {
      await cart.checkout({ inventoryChecker: checker });
      expect.unreachable("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      // Only first check triggers error; second is never reached
      expect(checker.check).toHaveBeenCalledTimes(1);
    }
  });
});
"}

