import { describe, it, expect } from "vitest";
import {
  NoDiscountPolicy,
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
  CompositeDiscountPolicy,
} from "../src/pricing.ts";

describe("NoDiscountPolicy", () => {
  const policy = new NoDiscountPolicy();

  it("returns 0 for positive subtotal", () => {
    expect(policy.computeDiscountCents(10000)).toBe(0);
  });

  it("returns 0 for zero subtotal", () => {
    expect(policy.computeDiscountCents(0)).toBe(0);
  });

  it("returns 0 for negative subtotal", () => {
    expect(policy.computeDiscountCents(-500)).toBe(0);
  });
});

describe("PercentageDiscountPolicy", () => {
  it("rejects negative percent", () => {
    expect(() => new PercentageDiscountPolicy(-1)).toThrow(RangeError);
  });

  it("rejects percent > 100", () => {
    expect(() => new PercentageDiscountPolicy(101)).toThrow(RangeError);
  });

  it("rejects NaN", () => {
    expect(() => new PercentageDiscountPolicy(NaN)).toThrow(RangeError);
  });

  it("rejects Infinity", () => {
    expect(() => new PercentageDiscountPolicy(Infinity)).toThrow(RangeError);
  });

  it("accepts 0%", () => {
    const p = new PercentageDiscountPolicy(0);
    expect(p.computeDiscountCents(10000)).toBe(0);
  });

  it("accepts 100%", () => {
    const p = new PercentageDiscountPolicy(100);
    expect(p.computeDiscountCents(10000)).toBe(10000);
  });

  it("computes 10% of 9999 (rounds down)", () => {
    const p = new PercentageDiscountPolicy(10);
    // 9999 * 10 / 100 = 999.9 → floor → 999
    expect(p.computeDiscountCents(9999)).toBe(999);
  });

  it("returns 0 for zero subtotal", () => {
    const p = new PercentageDiscountPolicy(50);
    expect(p.computeDiscountCents(0)).toBe(0);
  });

  it("returns 0 for negative subtotal", () => {
    const p = new PercentageDiscountPolicy(50);
    expect(p.computeDiscountCents(-100)).toBe(0);
  });

  it("handles very large subtotal", () => {
    const p = new PercentageDiscountPolicy(15);
    expect(p.computeDiscountCents(100_000_000)).toBe(15_000_000);
  });
});

describe("FixedAmountDiscountPolicy", () => {
  it("rejects negative amount", () => {
    expect(() => new FixedAmountDiscountPolicy(-1)).toThrow(RangeError);
  });

  it("rejects non-integer amount", () => {
    expect(() => new FixedAmountDiscountPolicy(10.5)).toThrow(RangeError);
  });

  it("accepts 0", () => {
    const p = new FixedAmountDiscountPolicy(0);
    expect(p.computeDiscountCents(5000)).toBe(0);
  });

  it("returns the fixed amount when subtotal exceeds it", () => {
    const p = new FixedAmountDiscountPolicy(500);
    expect(p.computeDiscountCents(5000)).toBe(500);
  });

  it("caps at subtotal when discount exceeds subtotal", () => {
    const p = new FixedAmountDiscountPolicy(5000);
    expect(p.computeDiscountCents(2000)).toBe(2000);
  });

  it("returns 0 for zero subtotal", () => {
    const p = new FixedAmountDiscountPolicy(500);
    expect(p.computeDiscountCents(0)).toBe(0);
  });

  it("returns 0 for negative subtotal", () => {
    const p = new FixedAmountDiscountPolicy(500);
    expect(p.computeDiscountCents(-100)).toBe(0);
  });
});

describe("CompositeDiscountPolicy", () => {
  it("rejects empty policy list", () => {
    expect(() => new CompositeDiscountPolicy([])).toThrow(
      "at least one policy",
    );
  });

  describe("sum mode", () => {
    it("sums discounts from all policies against original subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10), // 1000
          new FixedAmountDiscountPolicy(500), // 500
        ],
        "sum",
      );
      expect(composite.computeDiscountCents(10000)).toBe(1500);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(100)],
        "sum",
      );
      expect(composite.computeDiscountCents(-50)).toBe(0);
    });

    it("sum can exceed subtotal (Cart clamps later)", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new FixedAmountDiscountPolicy(800),
          new FixedAmountDiscountPolicy(800),
        ],
        "sum",
      );
      // Each gets min(800, 1000) = 800 → total 1600 > 1000
      expect(composite.computeDiscountCents(1000)).toBe(1600);
    });

    it("defaults to sum mode when mode omitted", () => {
      const composite = new CompositeDiscountPolicy([
        new PercentageDiscountPolicy(10),
        new FixedAmountDiscountPolicy(200),
      ]);
      // 10% of 5000 = 500, fixed 200 → 700
      expect(composite.computeDiscountCents(5000)).toBe(700);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially on remaining subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10), // 10% of 10000 = 1000
          new FixedAmountDiscountPolicy(500), // 500 off remaining 9000
        ],
        "chain",
      );
      expect(composite.computeDiscountCents(10000)).toBe(1500);
    });

    it("order matters in chain mode", () => {
      const policiesA = [
        new PercentageDiscountPolicy(50), // 50% of 10000 = 5000, remaining 5000
        new PercentageDiscountPolicy(50), // 50% of 5000 = 2500
      ];
      const policiesB = [
        new PercentageDiscountPolicy(50), // same result due to symmetry
        new PercentageDiscountPolicy(50),
      ];
      const a = new CompositeDiscountPolicy(policiesA, "chain");
      const b = new CompositeDiscountPolicy(policiesB, "chain");
      expect(a.computeDiscountCents(10000)).toBe(7500);
      expect(b.computeDiscountCents(10000)).toBe(7500);
    });

    it("chain cannot exceed subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new FixedAmountDiscountPolicy(600),
          new FixedAmountDiscountPolicy(600),
        ],
        "chain",
      );
      // First: min(600, 1000) = 600, remaining = 400
      // Second: min(600, 400) = 400, remaining = 0
      expect(composite.computeDiscountCents(1000)).toBe(1000);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(100)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("chain with percentage then fixed shows compounding", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(20), // 20% of 1000 = 200 → remaining 800
          new FixedAmountDiscountPolicy(300), // min(300,800) = 300
        ],
        "chain",
      );
      expect(composite.computeDiscountCents(1000)).toBe(500);
    });
  });
});

