import { describe, it, expect } from "vitest";
import {
  FreeShippingCalculator,
  FlatShippingCalculator,
  WeightBasedShippingCalculator,
} from "../src/shipping.ts";
import type { CartLine } from "../src/product.ts";

const line = (
  id: string,
  weightGrams: number,
  quantity = 1,
): CartLine => ({
  product: { id, name: id, unitPriceCents: 1000, weightGrams },
  quantity,
});

const noWeightLine = (id: string, quantity = 1): CartLine => ({
  product: { id, name: id, unitPriceCents: 1000 },
  quantity,
});

describe("FreeShippingCalculator", () => {
  const calc = new FreeShippingCalculator();

  it("returns 0 for any input", () => {
    expect(calc.computeShippingCents([line("a", 500)], 10000)).toBe(0);
  });

  it("returns 0 for empty cart", () => {
    expect(calc.computeShippingCents([], 0)).toBe(0);
  });
});

describe("FlatShippingCalculator", () => {
  it("rejects negative flatCents", () => {
    expect(() => new FlatShippingCalculator(-1)).toThrow(RangeError);
  });

  it("rejects non-integer flatCents", () => {
    expect(() => new FlatShippingCalculator(5.5)).toThrow(RangeError);
  });

  it("rejects negative freeOverCents", () => {
    expect(() => new FlatShippingCalculator(500, -1)).toThrow(RangeError);
  });

  it("rejects non-integer freeOverCents", () => {
    expect(() => new FlatShippingCalculator(500, 10.5)).toThrow(RangeError);
  });

  it("returns flat fee for normal cart", () => {
    const calc = new FlatShippingCalculator(599);
    expect(calc.computeShippingCents([line("a", 100)], 2000)).toBe(599);
  });

  it("returns 0 for empty cart", () => {
    const calc = new FlatShippingCalculator(599);
    expect(calc.computeShippingCents([], 0)).toBe(0);
  });

  it("returns 0 when subtotal meets free-over threshold", () => {
    const calc = new FlatShippingCalculator(599, 5000);
    expect(calc.computeShippingCents([line("a", 100)], 5000)).toBe(0);
  });

  it("returns 0 when subtotal exceeds free-over threshold", () => {
    const calc = new FlatShippingCalculator(599, 5000);
    expect(calc.computeShippingCents([line("a", 100)], 6000)).toBe(0);
  });

  it("returns flat fee when subtotal below free-over threshold", () => {
    const calc = new FlatShippingCalculator(599, 5000);
    expect(calc.computeShippingCents([line("a", 100)], 4999)).toBe(599);
  });

  it("accepts 0 flatCents", () => {
    const calc = new FlatShippingCalculator(0);
    expect(calc.computeShippingCents([line("a", 100)], 2000)).toBe(0);
  });

  it("accepts 0 freeOverCents (always free with items)", () => {
    const calc = new FlatShippingCalculator(500, 0);
    expect(calc.computeShippingCents([line("a", 100)], 0)).toBe(0);
  });
});

describe("WeightBasedShippingCalculator", () => {
  it("rejects empty brackets", () => {
    expect(() => new WeightBasedShippingCalculator([])).toThrow(
      "at least one weight bracket",
    );
  });

  it("rejects bracket with non-positive upToGrams", () => {
    expect(
      () =>
        new WeightBasedShippingCalculator([
          { upToGrams: 0, costCents: 100 },
        ]),
    ).toThrow(RangeError);
  });

  it("rejects bracket with negative costCents", () => {
    expect(
      () =>
        new WeightBasedShippingCalculator([
          { upToGrams: 1000, costCents: -1 },
        ]),
    ).toThrow(RangeError);
  });

  it("rejects non-integer overflowCostCents", () => {
    expect(
      () =>
        new WeightBasedShippingCalculator(
          [{ upToGrams: 1000, costCents: 500 }],
          10.5,
        ),
    ).toThrow(RangeError);
  });

  it("rejects negative overflowCostCents", () => {
    expect(
      () =>
        new WeightBasedShippingCalculator(
          [{ upToGrams: 1000, costCents: 500 }],
          -1,
        ),
    ).toThrow(RangeError);
  });

  it("returns 0 for empty cart", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 1000, costCents: 500 },
    ]);
    expect(calc.computeShippingCents([], 1000)).toBe(0);
  });

  it("returns 0 when total weight is 0", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 1000, costCents: 500 },
    ]);
    expect(calc.computeShippingCents([noWeightLine("a")], 1000)).toBe(0);
  });

  it("selects the correct bracket", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 600 },
      { upToGrams: 5000, costCents: 1200 },
    ]);
    expect(calc.computeShippingCents([line("a", 400)], 1000)).toBe(300);
    expect(calc.computeShippingCents([line("a", 500)], 1000)).toBe(300); // boundary
    expect(calc.computeShippingCents([line("a", 501)], 1000)).toBe(600);
    expect(calc.computeShippingCents([line("a", 1000)], 1000)).toBe(600);
    expect(calc.computeShippingCents([line("a", 1001)], 1000)).toBe(1200);
  });

  it("sorts brackets regardless of input order", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 5000, costCents: 1200 },
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 600 },
    ]);
    expect(calc.computeShippingCents([line("a", 400)], 1000)).toBe(300);
    expect(calc.computeShippingCents([line("a", 700)], 1000)).toBe(600);
  });

  it("uses overflow cost when weight exceeds all brackets", () => {
    const calc = new WeightBasedShippingCalculator(
      [
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 1000, costCents: 600 },
      ],
      2000,
    );
    expect(calc.computeShippingCents([line("a", 1500)], 1000)).toBe(2000);
  });

  it("falls back to heaviest bracket cost when no overflow specified", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 600 },
    ]);
    expect(calc.computeShippingCents([line("a", 5000)], 1000)).toBe(600);
  });

  it("handles multiple lines for weight calculation", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 1000, costCents: 500 },
      { upToGrams: 2000, costCents: 900 },
    ]);
    // 300*2 + 500*1 = 1100 → bracket 2
    const lines = [line("a", 300, 2), line("b", 500, 1)];
    expect(calc.computeShippingCents(lines, 1000)).toBe(900);
  });
});

