import { describe, it, expect, vi } from "vitest";
import {
  InventoryError,
  refreshPrices,
  type PriceFetcher,
} from "../src/inventory.ts";
import type { CartLine } from "../src/product.ts";

describe("InventoryError", () => {
  it("has the expected shape", () => {
    const err = new InventoryError("out of stock", "p1", 5, 2);
    expect(err).toBeInstanceOf(Error);
    expect(err).toBeInstanceOf(InventoryError);
    expect(err.name).toBe("InventoryError");
    expect(err.message).toBe("out of stock");
    expect(err.productId).toBe("p1");
    expect(err.requested).toBe(5);
    expect(err.available).toBe(2);
  });

  it("available can be undefined", () => {
    const err = new InventoryError("gone", "p2", 1, undefined);
    expect(err.available).toBeUndefined();
  });
});

describe("refreshPrices", () => {
  const makeLine = (id: string, price: number, qty = 1): CartLine => ({
    product: { id, name: id, unitPriceCents: price },
    quantity: qty,
  });

  it("updates prices from fetcher", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn()
        .mockResolvedValueOnce(1500)
        .mockResolvedValueOnce(2500),
    };
    const lines = [makeLine("a", 1000), makeLine("b", 2000)];
    const result = await refreshPrices(lines, fetcher);
    expect(result[0]!.product.unitPriceCents).toBe(1500);
    expect(result[1]!.product.unitPriceCents).toBe(2500);
    expect(result[0]!.quantity).toBe(1);
  });

  it("preserves other product fields", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(999),
    };
    const lines: CartLine[] = [
      {
        product: { id: "x", name: "Widget", unitPriceCents: 500, weightGrams: 200, currency: "EUR" },
        quantity: 3,
      },
    ];
    const result = await refreshPrices(lines, fetcher);
    expect(result[0]!.product.name).toBe("Widget");
    expect(result[0]!.product.weightGrams).toBe(200);
    expect(result[0]!.product.currency).toBe("EUR");
    expect(result[0]!.quantity).toBe(3);
  });

  it("throws RangeError for negative price", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(-1),
    };
    await expect(refreshPrices([makeLine("a", 100)], fetcher)).rejects.toThrow(
      RangeError,
    );
  });

  it("throws RangeError for non-integer price", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(10.5),
    };
    await expect(refreshPrices([makeLine("a", 100)], fetcher)).rejects.toThrow(
      RangeError,
    );
  });

  it("propagates fetcher rejection", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("fetch failed")),
    };
    await expect(refreshPrices([makeLine("a", 100)], fetcher)).rejects.toThrow(
      "fetch failed",
    );
  });

  it("returns empty array for empty lines", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn(),
    };
    const result = await refreshPrices([], fetcher);
    expect(result).toEqual([]);
    expect(fetcher.fetchPriceCents).not.toHaveBeenCalled();
  });
});

