+describe("Cart – checkout()", () => {
+  it("basic checkout without collaborators", async () => {
+    const cart = new Cart();
+    cart.add(product("a", 1000), 2);
+    const result = await cart.checkout();
+    expect(result.totals.subtotalCents).toBe(2000);
+    expect(result.lines).toHaveLength(1);
+  });
+
+  it("refreshes prices via priceFetcher", async () => {
+    const cart = new Cart();
+    cart.add(product("a", 1000), 1);
+    const fetcher: PriceFetcher = {
+      fetchPriceCents: vi.fn().mockResolvedValue(1500),
+    };
+    const result = await cart.checkout({ priceFetcher: fetcher });
+    expect(result.totals.subtotalCents).toBe(1500);
+    expect(fetcher.fetchPriceCents).toHaveBeenCalledWith("a");
+  });
+
+  it("checks inventory and passes when available", async () => {
+    const cart = new Cart();
+    cart.add(product("a", 1000), 2);
+    const checker: InventoryChecker = {
+      check: vi.fn().mockResolvedValue({ available: true }),
+    };
+    const result = await cart.checkout({ inventoryChecker: checker });
+    expect(result.totals.subtotalCents).toBe(2000);
+    expect(checker.check).toHaveBeenCalledWith("a", 2);
+  });
+
+  it("throws InventoryError when item not available", async () => {
+    const cart = new Cart();
+    cart.add(product("a", 1000), 5);
+    const checker: InventoryChecker = {
+      check: vi.fn().mockResolvedValue({
+        available: false,
+        availableQuantity: 2,
+        reason: "low stock",
+      }),
+    };
+    try {
+      await cart.checkout({ inventoryChecker: checker });
+      expect.unreachable("should have thrown");
+    } catch (err) {
+      expect(err).toBeInstanceOf(InventoryError);
+      const ie = err as InventoryError;
+      expect(ie.productId).toBe("a");
+      expect(ie.requested).toBe(5);
+      expect(ie.available).toBe(2);
+    }
+  });
+
+  it("throws InventoryError on partial-stock denial (available:true but quantity insufficient)", async () => {
+    const cart = new Cart();
